const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const address_input = require('input_field')
const qr_code = require('qr_code')

module.exports = receive_btc

async function receive_btc(opts = {}, callbacks = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  // Extract callbacks passed by action_buttons
  const onGenerate = callbacks.onGenerate || null
  const onUpdateDescription = callbacks.onUpdateDescription || null
  const onClose = callbacks.onClose || null

  const on = {
    style: inject,
    data: ondata,
    icons: iconject
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []
  let _currentAddress = ''

  shadow.innerHTML = `
    <div class="receive-btc-container">
      <div class="receive-btc-close">
        <div class="x-icon"></div>
      </div>
      <div class="receive-btc-header">
        <div class="title-container">
          <div class="receive-btc-title">Receive BTC</div>
          <div class="btc-icon"></div>
        </div>
      </div>

      <!-- Loading skeleton shown while address is being generated -->
      <div class="loading-state">
        <div class="skeleton skeleton-qr"></div>
        <div class="skeleton skeleton-addr"></div>
        <div class="loading-text">Generating address…</div>
      </div>

      <!-- Content shown once address is ready -->
      <div class="address-content hidden">
        <div class="qr-code"></div>
        <div class="address-input"></div>

        <div class="description-row">
          <label class="description-label">Tag (optional)</label>
          <div class="description-field">
            <input
              type="text"
              class="description-input"
              placeholder="e.g. Rent, Consulting…"
            />
            <button class="update-desc-btn">Add Tag</button>
          </div>
          <div class="desc-status"></div>
        </div>
      </div>

      <div class="generate-status"></div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const address_input_slot = shadow.querySelector('.address-input')
  const qr_code_slot = shadow.querySelector('.qr-code')
  const statusEl = shadow.querySelector('.generate-status')
  const descInput = shadow.querySelector('.description-input')
  const updateDescBtn = shadow.querySelector('.update-desc-btn')
  const descStatus = shadow.querySelector('.desc-status')
  const loadingState = shadow.querySelector('.loading-state')
  const addressContent = shadow.querySelector('.address-content')

  const subs = await sdb.watch(onbatch)

  const qr_component = await qr_code(subs[0])
  const address_component = await address_input(subs[1])

  qr_code_slot.append(qr_component)
  address_input_slot.append(address_component)

  const closeBtn = shadow.querySelector('.x-icon')
  if (closeBtn) {
    closeBtn.onclick = () => {
      if (onClose) {
        onClose()
      } else {
        const dropdown = el.parentNode
        if (dropdown) dropdown.classList.add('hidden')
      }
    }
  }

  // ---- Update Description button ----
  updateDescBtn.onclick = () => {
    const desc = descInput.value.trim()
    if (!_currentAddress) return
    if (!desc) {
      descStatus.textContent = '⚠️ Please enter a description first'
      descStatus.style.color = '#e74c3c'
      setTimeout(() => { descStatus.textContent = '' }, 2500)
      return
    }

    updateDescBtn.disabled = true
    descStatus.textContent = '⏳ Updating…'
    descStatus.style.color = '#888'

    if (typeof onUpdateDescription === 'function') {
      onUpdateDescription(_currentAddress, desc)
    } else {
      updateDescBtn.disabled = false
      descStatus.textContent = '⚠️ Backend not connected'
      descStatus.style.color = '#e74c3c'
    }
  }

  // Public API: called by action_buttons when backend returns a real address
  el.setAddress = function (addr) {
    _currentAddress = addr

    loadingState.classList.add('hidden')
    addressContent.classList.remove('hidden')

    if (!addr) {
      statusEl.textContent = '❌ Failed to generate address'
      statusEl.style.color = '#e74c3c'
      return
    }

    statusEl.textContent = '✅ Address ready'
    statusEl.style.color = '#2ecc71'

    // Update QR via the qr_code component's public API
    if (typeof qr_component.setAddress === 'function') {
      qr_component.setAddress(addr)
    }

    // Update address text field
    if (typeof address_component.setValue === 'function') {
      address_component.setValue(addr)
    } else {
      address_input_slot.innerHTML = ''
      const addrEl = document.createElement('div')
      addrEl.style.cssText = `
        font-family: monospace;
        font-size: 12px;
        word-break: break-all;
        padding: 10px 12px;
        background: rgba(247,147,26,0.08);
        border: 1px solid rgba(247,147,26,0.3);
        border-radius: 8px;
        display: flex;
        align-items: center;
        gap: 8px;
        width: 100%;
        box-sizing: border-box;
      `
      const addrText = document.createElement('span')
      addrText.style.cssText = 'flex:1; color:#222; word-break:break-all;'
      addrText.textContent = addr

      const copyBtn = document.createElement('span')
      copyBtn.style.cssText = 'cursor:pointer; flex-shrink:0; color:#f7931a;'
      copyBtn.title = 'Copy address'
      copyBtn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>`

      copyBtn.onclick = async () => {
        try {
          await navigator.clipboard.writeText(addr)
          copyBtn.style.color = '#27ae60'
          setTimeout(() => { copyBtn.style.color = '#f7931a' }, 1200)
        } catch (err) {
          const ta = document.createElement('textarea')
          ta.value = addr
          document.body.appendChild(ta)
          ta.select()
          document.execCommand('copy')
          document.body.removeChild(ta)
        }
      }

      addrEl.appendChild(addrText)
      addrEl.appendChild(copyBtn)
      address_input_slot.appendChild(addrEl)
    }

    setTimeout(() => { statusEl.textContent = '' }, 3000)
  }

  // Public API: called by action_buttons when description update resolves
  el.onDescriptionUpdated = function (success) {
    updateDescBtn.disabled = false
    if (success) {
      descStatus.textContent = '✅ Description saved'
      descStatus.style.color = '#2ecc71'
    } else {
      descStatus.textContent = '❌ Failed to update description'
      descStatus.style.color = '#e74c3c'
    }
    setTimeout(() => { descStatus.textContent = '' }, 3000)
  }

  // Public API: called by action_buttons on every reopen to get a fresh address
  el.reset = function () {
    _currentAddress = ''
    descInput.value = ''
    descStatus.textContent = ''
    statusEl.textContent = ''
    updateDescBtn.disabled = false
    address_input_slot.innerHTML = ''
    address_input_slot.append(address_component)

    // Clear QR
    if (typeof qr_component.setAddress === 'function') {
      qr_component.setAddress('')
    }

    // Back to loading skeleton
    addressContent.classList.add('hidden')
    loadingState.classList.remove('hidden')

    // Request fresh address
    if (typeof onGenerate === 'function') {
      onGenerate('Payment')
    }
  }

  // Auto-generate on first mount
  if (typeof onGenerate === 'function') {
    onGenerate('Payment')
  }

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(f => f.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    const base = data[0] || ''
    style.textContent = base + `
      .hidden { display: none !important; }

      .loading-state {
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 14px;
        padding: 8px 0;
      }
      .skeleton {
        border-radius: 10px;
        background: linear-gradient(90deg, rgba(255,255,255,0.08) 25%, rgba(255,255,255,0.18) 50%, rgba(255,255,255,0.08) 75%);
        background-size: 200% 100%;
        animation: shimmer 1.4s infinite;
      }
      .skeleton-qr {
        width: 220px;
        height: 220px;
        border-radius: 12px;
      }
      .skeleton-addr {
        width: 100%;
        height: 42px;
        border-radius: 8px;
      }
      .loading-text {
        font-size: 13px;
        color: #888;
        letter-spacing: 0.3px;
      }
      @keyframes shimmer {
        0%   { background-position: 200% 0; }
        100% { background-position: -200% 0; }
      }

      .address-content {
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 16px;
      }

      .description-row {
        width: 100%;
        display: flex;
        flex-direction: column;
        gap: 6px;
      }
      .description-label {
        font-size: 12px;
        font-weight: 600;
        color: #aaa;
        text-transform: uppercase;
        letter-spacing: 0.5px;
      }
      .description-field {
        display: flex;
        gap: 8px;
        align-items: center;
      }
      .description-input {
        flex: 1;
        box-sizing: border-box;
        padding: 10px 14px;
        border-radius: 8px;
        border: 1px solid rgba(255,255,255,0.15);
        background: rgba(255,255,255,0.07);
        color: #111;
        font-size: 14px;
        outline: none;
        transition: border-color 0.2s;
      }
      .description-input::placeholder { color: #666; }
      .description-input:focus { border-color: #f7931a; }

      .update-desc-btn {
        padding: 10px 16px;
        border-radius: 8px;
        border: none;
        background: linear-gradient(135deg, #f7931a, #f5a623);
        color: #fff;
        font-size: 13px;
        font-weight: 700;
        cursor: pointer;
        white-space: nowrap;
        transition: opacity 0.2s, transform 0.1s;
        letter-spacing: 0.2px;
      }
      .update-desc-btn:hover { opacity: 0.9; transform: translateY(-1px); }
      .update-desc-btn:active { transform: translateY(0); }
      .update-desc-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }

      .desc-status {
        font-size: 12px;
        min-height: 16px;
        text-align: left;
      }
      .generate-status {
        font-size: 13px;
        min-height: 18px;
        text-align: center;
      }
    `
  }

  function iconject(data) {
    dricons = data
    const btc_icon = shadow.querySelector('.btc-icon')
    const x_icon = shadow.querySelector('.x-icon')
    btc_icon.innerHTML = dricons[0] || ''
    x_icon.innerHTML = dricons[1] || '✖'
  }

  async function ondata(data) { }
}

function fallback_module() {
  return {
    api,
    _: {
      'input_field': { $: '' },
      'qr_code': { $: '' }
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const qr_code = {
      mapping: { style: 'style', data: 'data' },
      0: { address: '' }
    }

    const input_field = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      1: {
        header: 'Your bitcoin address',
        placeholder: 'Generating…',
        address: '',
        icon: 'apple'
      }
    }

    return {
      drive: {
        'icons/': { 'btc.svg': { '$ref': 'btc.svg' }, 'x.svg': { '$ref': 'x.svg' } },
        'style/': { 'receive_btc.css': { '$ref': 'receive_btc.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      },
      _: { qr_code, input_field }
    }
  }
}